import 'package:cloud_firestore/cloud_firestore.dart';
import 'package:firebase_auth/firebase_auth.dart';
import 'package:flutter/material.dart';
import '../services/healthline_firestore_service.dart';

class ChatDetailScreen extends StatefulWidget { final String hospital; final String? otherUid; final String? conversationId; const ChatDetailScreen({super.key,required this.hospital,this.otherUid,this.conversationId}); @override State<ChatDetailScreen> createState()=>_ChatDetailScreenState(); }
class _ChatDetailScreenState extends State<ChatDetailScreen>{final controller=TextEditingController();final scroll=ScrollController();String? conversationId;bool opening=false;static const bg=Color(0xFF101010),surface=Color(0xFF1C1A1A),mauve=Color(0xFFB78A9B),muted=Color(0xFFAAAAAA);
 @override void initState(){super.initState();conversationId=widget.conversationId;if(conversationId==null&&widget.otherUid!=null){opening=true;HealthLineFirestoreService.instance.getOrCreateConversation(widget.otherUid!).then((id){if(mounted)setState(()=>conversationId=id);}).catchError((e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('Could not open conversation: $e')));}).whenComplete(() { if (mounted) setState(() => opening = false); });}}
 @override void dispose(){controller.dispose();scroll.dispose();super.dispose();}
 Future<void> send()async{final text=controller.text.trim();final id=conversationId;if(text.isEmpty||id==null)return;controller.clear();try{await HealthLineFirestoreService.instance.sendMessage(id,text);}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('Message not sent: $e')));}}
 @override Widget build(BuildContext context)=>Scaffold(backgroundColor:bg,appBar:AppBar(backgroundColor:bg,foregroundColor:Colors.white,title:Text(widget.hospital)),body:Column(children:[Expanded(child:conversationId==null?Center(child:Text(opening?'Opening conversation…':'Open this chat from Messages after a conversation exists.',style:const TextStyle(color:muted))):StreamBuilder<QuerySnapshot<Map<String,dynamic>>>(stream:HealthLineFirestoreService.instance.conversationMessages(conversationId!),builder:(context,s){if(s.hasError)return Center(child:Text('${s.error}',style:const TextStyle(color:Colors.redAccent)));if(!s.hasData)return const Center(child:CircularProgressIndicator());final docs=s.data!.docs;return ListView(padding:const EdgeInsets.all(16),children:docs.map((d){final data=d.data();final mine=data['senderUid']==FirebaseAuth.instance.currentUser?.uid;return Align(alignment:mine?Alignment.centerRight:Alignment.centerLeft,child:Container(margin:const EdgeInsets.only(bottom:10),padding:const EdgeInsets.symmetric(horizontal:14,vertical:10),constraints:const BoxConstraints(maxWidth:300),decoration:BoxDecoration(color:mine?mauve:surface,borderRadius:BorderRadius.circular(16)),child:Text((data['text']??'').toString(),style:TextStyle(color:mine?Colors.white:Colors.white70))));}).toList());})),SafeArea(top:false,child:Padding(padding:const EdgeInsets.all(12),child:Row(children:[Expanded(child:TextField(controller:controller,style:const TextStyle(color:Colors.white),decoration:InputDecoration(hintText:'Write a message…',hintStyle:const TextStyle(color:muted),filled:true,fillColor:surface,border:OutlineInputBorder(borderRadius:BorderRadius.circular(24),borderSide:BorderSide.none)),onSubmitted:(_)=>send())),const SizedBox(width:8),IconButton(onPressed:send,icon:const Icon(Icons.send_rounded,color:mauve))])))]));}
